/**
 * A guardian chip's upgrade table as a chart: every level of each of its three stats, with what
 * that level costs. The same layout the bot and ultimate weapon charts use, for the one upgrade
 * ladder that had no chart.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    buildGuardianUpgradesDataset
 * depends    src/charts/tables/types, src/data
 * used by    src/calculators/specs.generated, src/charts/datasets/index, src/charts/index, src/charts/tables/lookup
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { findGuardianDefinition, getGuardianStatBounds } from '../../data'
import type { SharedChartTableDataset } from '../tables/types'

/**
 * The upgrade table for one chip, or `null` when no chip has that name.
 *
 * A chip's three stats stop at different levels, so the table is as long as the longest and a
 * shorter stat's cells are blank past its own last level — blank, not zero, because there is no
 * such level to buy. Levels count from 0, the stat as the chip starts.
 */
export function buildGuardianUpgradesDataset(
  guardianKey: string,
): SharedChartTableDataset<Record<string, unknown>> | null {
  const guardian = findGuardianDefinition(guardianKey)
  if (!guardian) return null

  const lastLevel = Math.max(0, ...guardian.statOrder.map((_, index) => getGuardianStatBounds(guardian, index).max))
  const columns = [
    { key: 'level', label: 'Level' },
    ...guardian.statOrder.flatMap((statName, index) => [
      { key: `value${index}`, label: statName },
      { key: `cost${index}`, label: `${statName} Cost` },
    ]),
  ]

  const rows: Record<string, unknown>[] = []
  for (let level = 0; level <= lastLevel; level += 1) {
    const row: Record<string, unknown> = { level }
    guardian.statOrder.forEach((statName, index) => {
      const entry = guardian.stats[statName]?.levels[level]
      row[`value${index}`] = entry?.value ?? ''
      row[`cost${index}`] = entry?.value == null ? '' : (entry.cost ?? '')
    })
    rows.push(row)
  }

  return { title: `${guardian.label} Chip Upgrades`, columns, rows }
}
